/**
 * High-resolution crops for each hotspot, exported from NASA's LROC WAC image service.
 *
 * Generated by the recipe in the demo's ATTRIBUTION.md; edit that, not this list. Each crop is
 * a lon/lat bounding box, so the runtime places it on the sphere without any guesswork: the
 * patch geometry follows the same convention as the global atlas, `u = (lon + 180) / 360` and
 * `v = (90 - lat) / 180`, and the image fills that box exactly.
 */

import { SITE_BUMP_SCALE } from './siteBumps'
import { SITE_RELIEF, type SiteRelief } from './siteRelief'

export interface MoonSite {
  id: string
  /** [west, south, east, north]; east passes 180 for a box crossing the antimeridian. */
  bbox: [number, number, number, number]
  width: number
  height: number
  /**
   * Hue multiplier that lines the grey crop up with the atlas: the crop's brightness already
   * matches, this only corrects the colour cast.
   */
  tint: [number, number, number]
}

/**
 * Where a crop sits in its feature's drill-down. Levels are shown in this order and each one
 * fades in once it covers the viewport on its own:
 *
 * - `wide`  a regional WAC crop, which is what the arrival flight is framed around;
 * - `fine`  the WAC crop the feature has always had, about ten times sharper;
 * - `nac`   an LROC Narrow Angle Camera mosaic over roughly 10-20 km;
 * - `nac-close` the same mosaic at its own pixel scale, one to six kilometres across.
 */
export type MoonSiteTier = 'wide' | 'fine' | 'nac' | 'nac-close'

const TIER_ORDER: MoonSiteTier[] = ['wide', 'fine', 'nac', 'nac-close']

/** Tier of a crop, which the id encodes: `<feature>`, `<feature>-wide`, `<feature>-nac`, ... */
export function siteTier(id: string): MoonSiteTier {
  if (id.endsWith('-nac-close')) return 'nac-close'
  if (id.endsWith('-nac')) return 'nac'
  if (id.endsWith('-wide')) return 'wide'
  return 'fine'
}

