export function findSite(id: string): MoonSite | null {
  return MOON_SITES.find((site) => site.id === id) ?? null
}

/**
 * Bump strength for a crop, or null when the feature has no relief map. The number is a
 * multiplier on the globe's own bump scale; `siteBumps.ts` explains where it comes from.
 */
export function siteBumpScale(id: string): number | null {
  return SITE_BUMP_SCALE[id] ?? null
}

/** Absolute LOLA range used to move a crop's vertices onto the lunar terrain. */
export function siteRelief(id: string): SiteRelief | null {
  return SITE_RELIEF[id] ?? null
}

/**
 * Detail levels for a feature, coarsest first: the wide crop carries the view from a regional
 * altitude, the fine crop takes over as the camera closes in, and the NAC crops finish the
 * descent. Features with fewer tiers simply skip the missing ones.
 */
export function siteLevels(featureId: string): MoonSite[] {
  return TIER_ORDER.map((tier) => findSite(tier === 'fine' ? featureId : `${featureId}-${tier}`))
    .filter((site): site is MoonSite => site !== null)
}

/**
 * The crop that decides how close the camera may come. A feature with NAC imagery chains three
 * or four tiers, and the floor has to follow the deepest of them: the descent would otherwise
 * stall at the wide crop's limit, long before the NAC crops fade in. Features whose drill-down
 * stops at the WAC crops keep the wide crop's floor, which is what the demo has always used.
 */
export function siteFloorSite(featureId: string): MoonSite | null {
  const levels = siteLevels(featureId)
  const deepest = levels[levels.length - 1]
  if (!deepest) return null
  const tier = siteTier(deepest.id)
  return tier === 'nac' || tier === 'nac-close' ? deepest : levels[0]
}

/** Crops that make up a feature's drill-down, used by the tests to check the tier ordering. */
export function siteTiers(featureId: string): MoonSiteTier[] {
  return siteLevels(featureId).map((site) => siteTier(site.id))
}
